-- The version of a person: starts at 0 and goes up by one each time the person is saved. An edit
-- carries the version its form loaded, and is refused when the person has been saved since.
ALTER TABLE person ADD COLUMN version BIGINT NOT NULL DEFAULT 0;
-- A statement taken for a person records their due-total at that moment and binds each of their
-- claims that counts then to the figure it had: a bound claim shows and totals stated_due (NULL:
-- n/a, no rate then) whatever rates or grades do later, until the person's next statement rebinds
-- their counting claims and unbinds the rest. A settled claim's settled_due still comes first.
ALTER TABLE claim ADD COLUMN stated BOOLEAN DEFAULT FALSE NOT NULL;
ALTER TABLE claim ADD COLUMN stated_due DECIMAL(12, 2);
-- statement_count: statements taken for the person; stated_total: the last one's due-total (NULL:
-- none taken, or n/a); statement_date: the sheet's today when the last one was taken.
ALTER TABLE person ADD COLUMN statement_count INT DEFAULT 0 NOT NULL;
ALTER TABLE person ADD COLUMN stated_total DECIMAL(12, 2);
ALTER TABLE person ADD COLUMN statement_date DATE;
-- The periods of a sheet, listed by from-date. name: unique on the sheet, compared without regard to
-- case and stored without surrounding spaces; from_date to to_date, both inclusive, from <= to. No
-- two periods of a sheet overlap. A claim belongs to the period whose dates contain its date, or none.
CREATE TABLE period (
    id        BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id  VARCHAR(100) NOT NULL,
    name      VARCHAR(200) NOT NULL,
    name_key  VARCHAR(200) GENERATED ALWAYS AS (LOWER(name)),
    from_date DATE         NOT NULL,
    to_date   DATE         NOT NULL,
    CHECK (from_date <= to_date)
);
CREATE UNIQUE INDEX period_sheet_name ON period (sheet_id, name_key);
-- A closed period keeps the due-total it had when it was closed (closed_total), whatever rates do
-- later. No claim dated inside a closed period may be added, edited, opened, settled or voided.
ALTER TABLE period ADD COLUMN closed BOOLEAN DEFAULT FALSE NOT NULL;
ALTER TABLE period ADD COLUMN closed_total DECIMAL(12, 2);

