      await Promise.all([
        queryClient.invalidateQueries({ queryKey: peopleKey(sheet) }),
        queryClient.invalidateQueries({ queryKey: claimsKey(sheet) }),
      ]);
      setName('');
      setAmount('');
    },
  });

  return (
    <form
      onSubmit={(e) => {
        e.preventDefault();
        submitOnce(() => {
          add.reset();
          return add.mutateAsync({ name, amount });
        });
      }}
    >
      <label>
        Quick add{' '}
        <input
          data-testid="quick-name"
          placeholder="Name"
          value={name}
          onChange={(e) => {
            add.reset();
            setName(e.target.value);
          }}
        />
      </label>{' '}
      <input
        data-testid="quick-amount"
        placeholder="Amount"
        value={amount}
        onChange={(e) => {
          add.reset();
          setAmount(e.target.value);
        }}
      />{' '}
      <button type="submit" data-testid="quick-submit" disabled={add.isPending}>
        Add claim
      </button>
      {add.isError && (
        <span role="alert" data-testid="quick-error">
          {' '}
          {(add.error instanceof HttpError && add.error.status === 400 && add.error.reason)
            || 'The claim could not be added.'}
        </span>
      )}
    </form>
  );
}

function PersonForm({ sheet, editing, onDone }: { sheet: string; editing?: Person; onDone: () => void }) {
  const queryClient = useQueryClient();
  const [name, setName] = useState(editing?.name ?? '');
  const [grade, setGrade] = useState(editing?.grade ?? 'A');
  // The version of the person the editor loaded; the server refuses the save (409) when someone
  // else has saved the person since.
  const [version, setVersion] = useState(editing?.version);
  const [user] = useCurrentUser();
  const by = `?user=${encodeURIComponent(user ?? '')}`;
  const submitOnce = useSingleSubmit();
  const save = useMutation({
    mutationFn: (body: { name: string; grade: string; version?: number }) =>
      editing
        ? putJson<Person>(`${peoplePath(sheet)}/${editing.id}${by}`, body)
        : postJson<Person>(`${peoplePath(sheet)}${by}`, body),
    onSuccess: async () => {
      await queryClient.invalidateQueries({ queryKey: peopleKey(sheet) });
      if (editing) {
        onDone();
      } else {
        setName('');
        setGrade('A');
      }
    },
    onError: (error) => {
      if (!(editing && error instanceof HttpError && error.status === 409)) return;
      // Someone else saved the person: re-read the sheet and show the current values in the form.
      void queryClient.invalidateQueries({ queryKey: peopleKey(sheet) }).then(() => {
        const current = queryClient.getQueryData<Person[]>(peopleKey(sheet))?.find((p) => p.id === editing.id);
        if (!current) return;
        setName(current.name);
        setGrade(current.grade);
        setVersion(current.version);
      });
    },
  });

  return (
    <form
      onSubmit={(e) => {
        e.preventDefault();
        submitOnce(() => {
          save.reset();
          // A blank or already-used name is refused by the server (400), which shows the form's error.
          return save.mutateAsync({ name, grade, version });
        });
      }}
    >
      <label>
        Name{' '}
        <input
          data-testid="person-form-name"
          value={name}
          onChange={(e) => {
            save.reset();
            setName(e.target.value);
          }}
        />
      </label>{' '}
      <label>
        Grade{' '}
        <select
          data-testid="person-form-grade"
          value={grade}
          onChange={(e) => {
            save.reset();
            setGrade(e.target.value);
          }}
        >
          {GRADES.map((g) => (
            <option key={g} value={g}>
              {g}
            </option>
          ))}
        </select>
      </label>{' '}
      <button type="submit" data-testid="person-form-submit" disabled={save.isPending}>
        {editing ? 'Save' : 'Add'}
      </button>
      {editing && (
        <button type="button" onClick={onDone}>
          Cancel
        </button>
      )}
      {save.isError && (
        <span role="alert" data-testid="person-form-error">
          {' '}
          {(save.error instanceof HttpError && (save.error.status === 400 || save.error.status === 409) && save.error.reason)
            || 'The person could not be saved.'}
        </span>
      )}
    </form>
  );
}
import { createFileRoute } from '@tanstack/react-router';
import { SignIn, useCurrentUser } from '../features/session/SignIn';
import { SheetPicker, useSheetId } from '../features/session/SheetPicker';
import { SheetToday } from '../features/sheet/SheetToday';
import { People } from '../features/people/People';
import { Rates } from '../features/rates/Rates';
import { Periods } from '../features/periods/Periods';

// The one screen. Sign in by name, then load a sheet by id; everything else is per sheet.
export const Route = createFileRoute('/')({
  component: Home,
});

function Home() {
  const [user] = useCurrentUser();
  const sheet = useSheetId();
  return (
    <>
      <SignIn />
      {user && <SheetPicker />}
      {user && sheet && <SheetToday sheet={sheet} />}
      {user && sheet && <Rates sheet={sheet} />}
      {user && sheet && <Periods sheet={sheet} />}
      {user && sheet && <People sheet={sheet} />}
      {user && !sheet && <p data-testid="home-empty">Nothing here yet.</p>}
    </>
  );
}
// The app's fetch surface. A non-2xx REJECTS, so useQuery/useMutation surface the failure instead
// of a silent `if (res.ok)` that leaves the UI showing stale data.
// A refused request: `reason` is the server's explanation (the response text), for the screen.
export class HttpError extends Error {
  constructor(message: string, readonly status: number, readonly reason: string) {
    super(message);
  }
}

async function send<T>(path: string, init?: RequestInit): Promise<T> {
  const res = await fetch(path, init);
  if (!res.ok) {
    const reason = await res.text().catch(() => '');
    throw new HttpError(`${init?.method ?? 'GET'} ${path} -> ${res.status}`, res.status, reason);
  }
  return res.status === 204 ? (undefined as T) : ((await res.json()) as T);
}

export function getJson<T>(path: string): Promise<T> {
  return send<T>(path);
}

export function postJson<T>(path: string, body: unknown): Promise<T> {
  return send<T>(path, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(body),
  });
}

export function putJson<T>(path: string, body: unknown): Promise<T> {
  return send<T>(path, {
    method: 'PUT',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(body),
  });
}
import { useRef } from 'react';

// A form submitted again before its first submit has answered sends nothing more: a double click on
// submit stores one record, not two. The `disabled={isPending}` on a submit button is not enough on
// its own, as a second click can land before the button re-renders disabled.
export function useSingleSubmit(): (submit: () => Promise<unknown>) => void {
  const busy = useRef(false);
  return (submit) => {
    if (busy.current) return;
    busy.current = true;
    // A refusal is shown through the mutation's error state; nothing more to do with it here.
    submit()
      .catch(() => undefined)
      .finally(() => {
        busy.current = false;
      });
  };
}
import { useNavigate, useSearch } from '@tanstack/react-router';

/**
 * Read and write ONE search-param key.
 *
 * State that outlives a click lives in the URL, not in a parent component — a filter, a sort, a
 * toggle, which row is selected. The control that owns a key is a self-contained file, and whoever
 * reads the key does so directly. Search params are an open namespace (declared once in
 * routes/__root.tsx), so a new key needs no schema change.
 *
 *     const [status, setStatus] = useSearchParam('status', asString);
 */
export function useSearchParam<T>(
  key: string,
  decode: (raw: unknown) => T,
): [T, (value: T | undefined) => void] {
  const search = useSearch({ strict: false }) as Record<string, unknown>;
  const navigate = useNavigate();

  const set = (value: T | undefined) => {
    void navigate({
      to: '.', // stay on the current route; only the search changes
      // Only the one key changes; every other param is left exactly as it was, so two controls
      // never clobber each other.
      search: (prev: Record<string, unknown>) => {
        const next = { ...prev };
        if (value === undefined || value === '') {
          delete next[key];
        } else {
          next[key] = value;
        }
        return next;
      },
      replace: true,
    });
  };

  return [decode(search[key]), set];
}

export const asString = (raw: unknown): string => (typeof raw === 'string' ? raw : '');
export const asNumber = (raw: unknown): number | undefined => {
  const n = Number(raw);
  return raw === undefined || raw === '' || Number.isNaN(n) ? undefined : n;
};
export const asFlag = (raw: unknown): boolean => raw === 'true' || raw === true;
import { useState } from 'react';
import { useQueryClient } from '@tanstack/react-query';
import { asString, useSearchParam } from '../../url/useSearchParam';

// Choose the active sheet by id. The active sheet is URL state (`sheet`); everything else is kept
// per sheet, under query keys starting ['sheet', id]. Loading an id (again) re-reads it from the store.
export function useSheetId(): string {
  return useSearchParam('sheet', asString)[0];
}

export function SheetPicker() {
  const [sheet, setSheet] = useSearchParam('sheet', asString);
  const [id, setId] = useState('');
  const queryClient = useQueryClient();

  return (
    <form
      onSubmit={(e) => {
        e.preventDefault();
        const trimmed = id.trim();
        if (!trimmed) return;
        setSheet(trimmed);
        void queryClient.invalidateQueries({ queryKey: ['sheet', trimmed] });
      }}
    >
      <label>
        Sheet <input data-testid="sheet-id-input" value={id} onChange={(e) => setId(e.target.value)} />
      </label>
      <button type="submit" data-testid="sheet-load">
        Load
      </button>
      {sheet && (
        <span>
          {' '}Active sheet: <strong data-testid="sheet-current-id">{sheet}</strong>
        </span>
      )}
    </form>
  );
}

